('SUBJECT_NOTES', '{"BAS-104":"https://drive.google.com/file/d/1EDX-DOk4zNUlIcBIri_yPdqAbHWVFMrg/view?usp=drive_link","BAS101":"https://drive.google.com/file/d/1UfvKTKg6F8Tqnj4EXdm0qIHvHyXvoE4A/view?usp=drive_link","BAS103":"https://drive.google.com/file/d/1UD9lq0bqQ6GCFtUoF275AgWiHCyJGmKh/view?usp=drive_link","BCS101":"https://drive.google.com/file/d/1O61tjW3SeACkS5Z1uuwwhatGHt4kqup9/view?usp=sharing","BEE101":"https://drive.google.com/file/d/1oN-SxUPtujpGTIhutNRVsJCogZg3af2g/view?usp=drive_link","BAS-205":"https://drive.google.com/file/d/1nsMETgHxQ9WRl0zoJO-XhxGRp7rbQTtW/view?usp=drive_link","BAS202":"https://drive.google.com/file/d/17TZ34ZcOiomPM1QCuFO-Uzedoc9hsC4O/view?usp=drive_link","BAS203":"https://drive.google.com/file/d/1Q-wYFAA6en_ADBGcv54KiT04rkp4700M/view?usp=drive_link","BEC201":"https://drive.google.com/file/d/1HnhLlS8CydYqBy6uz_lkEtCEphnhdcEK/view?usp=drive_link","BME201":"https://drive.google.com/file/d/1YyKWYqvDjDYTo0GH4nfh5vS2Lf_htIOX/view?usp=drive_link","BAS-301":"https://drive.google.com/file/d/1MkOTEsPYylrpeEtaMvXnik1f6mg05LAV/view?usp=drive_link","BAS-303/404":"https://drive.google.com/file/d/1Zju6gGphqAdyIuQE5NCt-qMGXphMDxLH/view?usp=drive_link","BCC-302":"https://drive.google.com/file/d/1STNJ9hOQ_X3ZBhHnGwqlSwImIYblna_b/view?usp=drive_link","BCS301":"https://drive.google.com/file/d/1Fem_shTfDQQ1TkuG2jbLTa6WpvOlpJeZ/view?usp=drive_link","BCS302":"https://drive.google.com/file/d/1rBomwQPyId3K_BYkTgpDTd-eD5YUcyLa/view?usp=drive_link","BCS303":"https://drive.google.com/file/d/1OWb1SKRBICkj9WJelL71XhviHjdFe6sR/view?usp=sharing","BCC-301":"https://drive.google.com/file/d/1_MQhHJiOJZA8mSf0HvwPZIkdWIL00tX5/view?usp=drive_link","BCS401":"https://drive.google.com/file/d/1LJXvOZZCZpY5dkdmNt8uRHV5zRGpXNlc/view?usp=drive_link","BCS402":"https://drive.google.com/file/d/19waynDVRWtOYHYaIrAtGfJsdoxivLdTL/view?usp=drive_link","BCS403":"https://drive.google.com/file/d/1IeGQkdPCLNlftYMaRHkQeUkK_hYN7BAP/view?usp=drive_link","BOE-410":"https://drive.google.com/file/d/1WVEgFKVJBCZ8_hBFHg6vpiu9_10-YxY1/view?usp=drive_link","BVE-401":"https://drive.google.com/file/d/1ygBfzIZkRWZuA6PZtdhS4V6-YoVCtlBK/view?usp=drive_link","BCS501":"https://drive.google.com/file/d/1LpVrqTtm_eWgOJwCKZ9YQ21rBUXs27K1/view?usp=drive_link","BCS502":"https://drive.google.com/file/d/1Tx2JR4ekVDxXHTxM98D9b_Gh49DHzFj4/view?usp=drive_link","BCS503":"https://drive.google.com/file/d/1fe1bzfCV95W_pGPO_FGLj-3lyPMHi2QR/view?usp=drive_link","BCS603":"https://drive.google.com/file/d/1D0YjrqkGEXK0rfnzeZrSg8Fy2NeTp6n0/view?usp=drive_link"}'::jsonb)
