insert into public.site_content (key, value) values
('SUBJECT_KB', '{"BAS101":{"name":"Engineering Physics","importance":"Engineering Physics builds your understanding of how the physical world works at a fundamental level. For CSE students, it directly connects to semiconductor physics (transistors, chips), fiber optic communication, laser technology, and quantum computing — the foundations of every electronic device your software runs on.","whyMatters":["Semiconductor physics explains how CPUs and transistors work","Fiber optics and lasers power internet communication","Quantum mechanics is the foundation of quantum computing","Superconductors and nanomaterials drive next-gen electronics"],"units":[{"title":"Unit I — Quantum Mechanics","short":"Wave-Particle Duality, Schrodinger","topics":["Inadequacy of classical mechanics, Planck theory of black body radiation","Compton effect, de-Broglie concept of matter waves","Davisson and Germer Experiment","Phase velocity and group velocity","Time-dependent and time-independent Schrodinger wave equations","Physical interpretation of wave function, Particle in a one-dimensional box"],"query":"Quantum+Mechanics+Engineering+Physics+BTech+Schrodinger+equation+AKTU"},{"title":"Unit II — Electromagnetic Field Theory","short":"Maxwell Equations, EM Waves","topics":["Stokes theorem and Divergence theorem","Basic laws of electricity and magnetism, Continuity equation","Displacement current, Maxwell equations (integral and differential form)","Maxwell equations in vacuum and conducting medium","Poynting vector and Poynting theorem","Plane electromagnetic waves, skin depth"],"query":"Maxwell+Equations+Electromagnetic+Field+Theory+Engineering+Physics+BTech"},{"title":"Unit III — Wave Optics","short":"Interference, Diffraction, Grating","topics":["Coherent sources, Interference in thin films (uniform and wedge-shaped)","Newton''s Rings and applications","Fraunhoffer diffraction at single slit and double slit, Absent spectra","Diffraction grating, Dispersive power, Resolving power","Rayleigh criterion of resolution, Resolving power of grating"],"query":"Wave+Optics+Interference+Diffraction+Grating+Engineering+Physics+BTech"},{"title":"Unit IV — Fiber Optics & Laser","short":"Optical Fiber, Laser Types","topics":["Fiber Optics: Acceptance angle, Numerical aperture, Step/Graded index fibers","Fiber optic communication, Attenuation, Dispersion","Laser: Spontaneous and stimulated emission, Population inversion","Einstein coefficients, Ruby laser and He-Ne laser","Laser applications in communication and medicine"],"query":"Fiber+Optics+Laser+Engineering+Physics+BTech+AKTU+numerical+aperture"},{"title":"Unit V — Superconductors & Nanomaterials","short":"Superconductors, Nano","topics":["Superconductors: Meissner effect, Critical field, Persistent current","Type I and Type II superconductors, High temperature superconductors","Nanomaterials: Quantum Dots, Quantum wires, Quantum well","Fabrication: CVD (Top-Down) and Sol Gel (Bottom-Up) approaches","Properties and applications of nanomaterials, Carbon Nano Tubes (CNT)"],"query":"Superconductors+Nanomaterials+Quantum+Dots+Engineering+Physics+BTech"}],"tips":[{"h":"Formula Sheet Daily","d":"<strong>Make a one-page formula sheet</strong> and revise it every day — 60% of marks come from formula-based numericals."},{"h":"Draw All Diagrams","d":"<strong>Draw ray diagrams, crystal structures, energy band diagrams</strong> — examiners give extra marks for neat labeled diagrams."},{"h":"Solve PYQs","d":"<strong>Solve last 5 years AKTU Physics papers</strong> — 70% of questions repeat each year with slight number changes."},{"h":"Link Lab to Theory","d":"<strong>Connect each practical to theory</strong> — Newton Rings experiment links to interference, it deepens understanding."}]},"BAS102":{"name":"Engineering Chemistry","importance":"Engineering Chemistry gives CSE students understanding of materials at molecular level. From batteries in laptops to corrosion in servers, from polymers in circuit boards to nanomaterials in chips — chemistry underpins all hardware your software runs on.","whyMatters":["Battery chemistry powers laptops, phones, EVs — all computing devices","Polymers used in PCBs, cables, and insulation of electronics","Nanomaterials and CNTs are foundation of next-gen chip fabrication","Water treatment chemistry is used in data center cooling systems"],"units":[{"title":"Unit I — Molecular Structure & Advanced Materials","short":"Nanomaterials, Green Chem","topics":["Molecular orbitals of diatomic molecules, Bond order, Magnetic characters","Liquid Crystals: types and applications (LCDs use liquid crystals)","Graphite and Fullerene: structure and applications","Nanomaterials: preparation, Carbon Nanotubes (CNT)","Green Chemistry: 12 principles, synthesis of Adipic acid and Paracetamol"],"query":"Engineering+Chemistry+Nanomaterials+Liquid+Crystals+Fullerene+BTech+AKTU"},{"title":"Unit II — Spectroscopy & Stereochemistry","short":"UV, IR, NMR, Isomerism","topics":["UV spectroscopy: principles and simple applications","IR spectroscopy: functional group identification","NMR spectroscopy: elementary idea and applications","Stereochemistry: optical isomerism, geometrical isomerism, chiral drugs"],"query":"Spectroscopy+UV+IR+NMR+Stereochemistry+Engineering+Chemistry+BTech"},{"title":"Unit III — Electrochemistry, Batteries & Corrosion","short":"Batteries, Corrosion","topics":["Electrochemistry basics, Primary cells (Dry cell), Secondary cells (Lead acid battery)","Corrosion: types, causes, prevention and control methods","Corrosion in power generation, chemical, oil & gas industries","Cement: constituents, manufacturing, hardening and setting","Plaster of Paris (POP)"],"query":"Electrochemistry+Batteries+Corrosion+Engineering+Chemistry+BTech+AKTU"},{"title":"Unit IV — Water Technology & Fuels","short":"Water Hardness, Calorific Values","topics":["Water: sources, impurities, hardness (temporary/permanent)","Water softening: Lime-Soda, Zeolite, Ion Exchange, Reverse Osmosis","Determination of hardness and alkalinity, Numerical problems","Fuels: Calorific value, Bomb Calorimeter, Dulong method","Coal: proximate and ultimate analysis, ranking of coal"],"query":"Water+Technology+Hardness+Fuels+Calorific+Value+Engineering+Chemistry+BTech"},{"title":"Unit V — Polymers & Organometallic Compounds","short":"Polymers, Applications","topics":["Polymers: classification, polymerization processes","Thermosetting vs Thermoplastic polymers","Conducting and biodegradable polymers","Important polymers: Teflon, Nylon, Bakelite, Kevlar, Dacron, Buna-N, Buna-S","Organometallic compounds: RMgX (Grignard), LiAlH4"],"query":"Polymers+Polymerization+Engineering+Chemistry+Teflon+Nylon+BTech+AKTU"}],"tips":[{"h":"Numerical Problems","d":"<strong>Practice water hardness and calorific value numericals daily</strong> — they appear in every AKTU Chemistry exam."},{"h":"Reactions & Equations","d":"<strong>Write balanced chemical equations</strong> for all reactions — marks deducted for wrong equations."},{"h":"Application Focus","d":"<strong>For each topic, note one real-life application</strong> — examiners award marks for relevant examples."},{"h":"PYQ Practice","d":"<strong>Solve AKTU last 5 years Chemistry papers</strong> — 65% questions repeat."}]},"BAS103":{"name":"Engineering Mathematics-I","importance":"Engineering Mathematics I is the universal language of engineering computation. Matrices power AI and ML algorithms, vector calculus describes electromagnetic fields, and differential calculus is used in optimization algorithms across all of software engineering and data science.","whyMatters":["Matrices and eigenvalues are the core of Machine Learning (PCA, SVD)","Vector calculus used in graphics, simulations, and physics engines","Differential calculus essential for gradient descent in AI training","Multiple integration used in probability distributions and statistics"],"units":[{"title":"Unit I — Matrices","short":"Eigenvalues, Cayley-Hamilton","topics":["Elementary transformations, Inverse of matrix, Rank of matrix","Solution of system of linear equations (Gauss elimination)","Characteristic equation, Cayley-Hamilton theorem and application","Linear Dependence and Independence of vectors","Eigen values and Eigen vectors","Complex Matrices: Hermitian, Skew-Hermitian, Unitary"],"query":"Matrices+Eigenvalues+Cayley+Hamilton+Engineering+Mathematics+BTech+AKTU"},{"title":"Unit II — Differential Calculus I","short":"Successive Diff, Euler Theorem","topics":["Successive differentiation (nth order derivatives), Leibnitz theorem","Curve tracing in Cartesian and polar coordinates","Partial derivatives, Euler theorem for homogeneous functions","Total derivative, Change of variables"],"query":"Differential+Calculus+Leibnitz+Euler+Theorem+Engineering+Mathematics+BTech"},{"title":"Unit III — Differential Calculus II","short":"Taylor, Maxima/Minima, Jacobians","topics":["Taylor series and Maclaurin series for one and two variables","Maxima and Minima of functions of several variables","Lagrange method of multipliers","Jacobians and change of variables","Approximation of errors"],"query":"Taylor+Series+Maxima+Minima+Lagrange+Jacobian+Engineering+Mathematics+BTech"},{"title":"Unit IV — Multiple Integration","short":"Double/Triple Integrals, Beta/Gamma","topics":["Double integral, Triple integral","Change of order of integration, Change of variables","Beta and Gamma functions and their properties","Dirichlet integral and application to area and volume","Liouville extension of Dirichlet integral"],"query":"Multiple+Integration+Double+Triple+Beta+Gamma+Dirichlet+BTech+Mathematics"},{"title":"Unit V — Vector Calculus","short":"Gradient, Divergence, Stokes, Gauss","topics":["Vector differentiation: Gradient, Curl, Divergence — physical interpretation","Directional derivatives","Vector Integration: Line integral, Surface integral, Volume integral","Gauss Divergence theorem, Green theorem, Stokes theorem (without proof)","Applications to engineering problems"],"query":"Vector+Calculus+Gradient+Divergence+Stokes+Gauss+Green+Engineering+Maths"}],"tips":[{"h":"Practice Daily","d":"<strong>Solve minimum 10 problems every day</strong> — Mathematics improves only through consistent daily practice, never by reading."},{"h":"B.S. Grewal Book","d":"Follow <strong>B.S. Grewal Higher Engineering Mathematics</strong> exclusively — it is perfectly aligned with AKTU Maths I syllabus."},{"h":"All Derivations","d":"<strong>Learn every standard derivation</strong> — AKTU theory asks 2-3 derivations in every paper."},{"h":"Unit by Unit","d":"<strong>Complete one full unit per week</strong> — do not mix topics, master one before moving next."}]},"BAS203":{"name":"Engineering Mathematics-II","importance":"Engineering Mathematics II introduces Laplace transforms used in signal processing, Fourier series used in audio/image compression, and complex variable theory used in control systems. These are directly applicable in DSP, telecommunications, and advanced computer graphics.","whyMatters":["Laplace transform used in signal processing and control systems","Fourier series/transform used in JPEG, MP3 compression algorithms","Complex variables used in electrical circuit analysis","ODE solutions model physical systems in simulations and games"],"units":[{"title":"Unit I — Ordinary Differential Equations","short":"ODE, Cauchy-Euler","topics":["Linear ODE of nth order with constant coefficients","Simultaneous linear differential equations","Second order ODE with variable coefficients: changing independent variable","Method of variation of parameters","Cauchy-Euler equation, engineering applications"],"query":"Ordinary+Differential+Equations+nth+order+Cauchy+Euler+Engineering+Maths+BTech"},{"title":"Unit II — Laplace Transform","short":"Laplace, Inverse, Convolution","topics":["Laplace transform definition, existence theorem","Properties: linearity, shifting, scaling","Laplace of derivatives and integrals","Unit step function, periodic function Laplace","Inverse Laplace transform, Convolution theorem","Solving ODEs and simultaneous DEs using Laplace"],"query":"Laplace+Transform+Inverse+Laplace+Convolution+Engineering+Mathematics+BTech"},{"title":"Unit III — Sequence, Series & Fourier","short":"Convergence, Fourier Series","topics":["Convergence of series: Ratio test, D Alembert test, Raabe test, Comparison test","Fourier series: definition, Euler coefficients","Half range Fourier sine and cosine series","Applications of Fourier series"],"query":"Fourier+Series+Convergence+Tests+Engineering+Mathematics+BTech+AKTU"},{"title":"Unit IV — Complex Variable (Differentiation)","short":"Analytic Functions, CR Equations","topics":["Functions of complex variable, continuity, differentiability","Analytic functions, Cauchy-Riemann equations (Cartesian and Polar)","Harmonic functions, Milne Thompson method","Conformal mapping, Mobius transformation"],"query":"Complex+Variable+Analytic+Functions+Cauchy+Riemann+Engineering+Mathematics"},{"title":"Unit V — Complex Variable (Integration)","short":"Cauchy Theorem, Residues","topics":["Complex integration, Cauchy integral theorem","Cauchy integral formula","Taylor series and Laurent series","Singularities: removable, poles, essential","Residues, Cauchy Residue theorem and applications"],"query":"Complex+Integration+Cauchy+Residue+Theorem+Taylor+Laurent+Engineering+Maths"}],"tips":[{"h":"Laplace Tables","d":"<strong>Memorize the standard Laplace transform table</strong> — at least 15 pairs are essential for solving exam problems quickly."},{"h":"Fourier Formulas","d":"<strong>Learn Euler coefficient formulas by heart</strong> and practice computing them for at least 5 different functions."},{"h":"CR Equations","d":"<strong>Practice checking analyticity using CR equations</strong> for 3-4 functions daily — common 5-mark question in AKTU."},{"h":"Residue Method","d":"<strong>Master Cauchy Residue theorem for evaluating real integrals</strong> — appears as a 10-mark question every year."}]},"BEE101":{"name":"Fundamentals of Electrical Engineering","importance":"Electrical Engineering fundamentals help CSE students understand how hardware actually works — from the power supply in your laptop to the motors in robots and IoT sensors. This subject is critical for embedded systems, IoT, and understanding the physical layer of all computing systems.","whyMatters":["Power supply circuits in every computing device use EE concepts","IoT devices require understanding of sensors and actuators","Data center power management and UPS systems","Understanding hardware-software interface for embedded systems"],"units":[{"title":"Unit I — DC Circuits","short":"KVL, KCL, Network Analysis","topics":["Electrical circuit elements: R, L, C — active and passive","Voltage and current sources, linearity, unilateral/bilateral elements","Kirchhoff Voltage Law (KVL) and Current Law (KCL)","Mesh analysis and nodal analysis","Network theorems: Thevenin, Norton, Superposition"],"query":"DC+Circuits+KVL+KCL+Thevenin+Norton+Fundamentals+Electrical+Engineering+BTech"},{"title":"Unit II — AC Circuits","short":"Phasors, Resonance, Power Factor","topics":["Representation of sinusoidal waveforms, RMS and average values","Analysis of R-L-C circuits (series and parallel)","Apparent, active and reactive power, Power factor","Resonance in series and parallel circuits, bandwidth, quality factor","Three phase balanced circuits, star and delta connections"],"query":"AC+Circuits+Phasors+Resonance+Power+Factor+Electrical+Engineering+BTech+AKTU"},{"title":"Unit III — Transformers","short":"Transformer Theory, Efficiency","topics":["Magnetic circuits, ideal and practical transformer","Equivalent circuit of transformer","Losses in transformers: copper loss, core loss","Voltage regulation and efficiency","Numerical problems on transformers"],"query":"Transformer+Equivalent+Circuit+Efficiency+Electrical+Engineering+BTech+AKTU"},{"title":"Unit IV — Electrical Machines","short":"DC Motors, Induction Motor","topics":["DC machines: principle, construction, EMF equation of generator","Torque equation of DC motor, applications","Three phase induction motor: principle, slip-torque characteristics","Single phase induction motor: starting methods","Synchronous machines: alternator and synchronous motor"],"query":"DC+Motor+Induction+Motor+Electrical+Machines+BTech+AKTU+slip+torque"},{"title":"Unit V — Electrical Installations","short":"MCB, ELCB, Earthing","topics":["Switch Fuse Unit (SFU), MCB, ELCB, MCCB, ACB — types and uses","Types of wires, cables, and bus-bars","Earthing: types and importance, lightning protection","Types of batteries: lead acid, lithium, alkaline"],"query":"Electrical+Installations+MCB+ELCB+Earthing+BTech+AKTU+safety"}],"tips":[{"h":"Circuit Diagrams","d":"<strong>Draw every circuit diagram neatly with all components labeled</strong> — examiners give marks even if calculation is slightly wrong."},{"h":"KVL/KCL Numericals","d":"<strong>Solve 5 mesh/nodal analysis problems daily</strong> — they appear in every AKTU EE exam."},{"h":"Transformer Numericals","d":"<strong>Practice efficiency, regulation, and loss calculations</strong> — guaranteed numerical question every year."},{"h":"Thevenin & Norton","d":"<strong>Master Thevenin and Norton equivalent circuit theorem</strong> — appears every AKTU exam as a 10-mark problem."}]},"BEC101":{"name":"Fundamentals of Electronics Engineering","importance":"Electronics Engineering introduces the hardware building blocks of all digital systems — diodes, transistors, op-amps, and digital logic gates. Every microprocessor, every chip, every circuit your software eventually runs on is built from these fundamental components.","whyMatters":["Diodes and transistors are inside every CPU and memory chip","Op-amps are in sensors and analog-to-digital converters for IoT","Digital logic gates are the foundation of all computer hardware","Communication fundamentals explain how the internet physically works"],"units":[{"title":"Unit I — Semiconductor Diode & Applications","short":"Diode, Rectifier, Zener","topics":["Semiconductor diode: depletion layer, V-I characteristics, ideal/practical","Zener diode: Zener and avalanche breakdown mechanisms","Rectification: half wave and full wave rectifiers, efficiency","Clippers, clampers, Zener shunt regulator","Special devices: LED, Photodiode, Varactor, Tunnel diode"],"query":"Semiconductor+Diode+Rectifier+Zener+Electronics+Engineering+BTech+AKTU"},{"title":"Unit II — BJT & FET","short":"Transistor, MOSFET, JFET","topics":["BJT: construction, operation, amplification action","Common Base, Common Emitter, Common Collector configurations","FET: JFET construction and V-I characteristics","MOSFET: Depletion and Enhancement type, Transfer characteristics"],"query":"BJT+FET+MOSFET+Transistor+Electronics+Engineering+BTech+AKTU"},{"title":"Unit III — Operational Amplifiers","short":"Op-Amp, Inverting, Integrator","topics":["Op-Amp basics: ideal vs practical, CMRR, Slew rate","Inverting and Non-inverting amplifier, Unity follower","Summing amplifier, Integrator, Differentiator","Comparators, Differential mode vs Common mode operation"],"query":"Operational+Amplifier+Op+Amp+Inverting+Integrator+Electronics+BTech+AKTU"},{"title":"Unit IV — Digital Electronics","short":"Number Systems, Logic Gates, K-Map","topics":["Number systems: binary, octal, hexadecimal — conversions","Binary arithmetic: addition, subtraction, multiplication","Basic gates: AND, OR, NOT, NAND, NOR, XOR, XNOR","Boolean algebra, simplification of Boolean functions","K-Map minimization up to 6 variables"],"query":"Digital+Electronics+Logic+Gates+Boolean+Algebra+K+Map+BTech+AKTU"},{"title":"Unit V — Communication Engineering","short":"Modulation, Wireless, Cellular","topics":["Signal representation, electromagnetic spectrum","Elements of communication system, need for modulation","Amplitude modulation (AM) and demodulation","Wireless communication: cellular systems, generations (2G/3G/4G/5G)","Satellite and radar communication fundamentals"],"query":"Communication+Engineering+Modulation+AM+FM+Wireless+BTech+AKTU"}],"tips":[{"h":"Diode Circuits","d":"<strong>Draw and analyze rectifier circuits</strong> with waveforms — examiners expect input/output waveform sketches."},{"h":"Transistor Configurations","d":"<strong>Memorize characteristics of all 3 BJT configurations</strong> — comparison table is a guaranteed question."},{"h":"K-Map Practice","d":"<strong>Practice K-Map minimization daily</strong> — 2, 3, 4 variable maps appear in every AKTU exam."},{"h":"Boolean Algebra","d":"<strong>Practice Boolean expression simplification</strong> using both Boolean algebra and K-Maps — both methods should be known."}]},"BCS101":{"name":"Programming for Problem Solving","importance":"Programming for Problem Solving is your first step into the world of software development. C language teaches you how a computer actually executes code — memory management, logic flow, and data structures. Every programming language you learn after this builds on exactly these concepts.","whyMatters":["Foundation for all future programming courses (Java, Python, DSA)","Pointers in C are used in OS, embedded systems, and compilers","Problem-solving logic from C directly helps in placement tests","Most competitive programming starts with C/C++ fundamentals"],"units":[{"title":"Unit I — Computer Basics & C Intro","short":"Computer Org, C Basics","topics":["Components of computer: memory, processor, I/O, storage","OS, compiler, interpreter, assembler, loader, linker concepts","Algorithm representation: flowchart, pseudocode","Structure of C program, syntax and logical errors","Data types, variables, memory, storage classes in C"],"query":"C+Programming+Basics+Computer+Fundamentals+BTech+AKTU+first+year"},{"title":"Unit II — Operators & Conditional Branching","short":"Operators, if-else, switch","topics":["Arithmetic, relational, logical, bitwise, assignment operators","Operator precedence and associativity","Type conversion, mixed operands","if, else-if, nested if-else statements","switch statement, break, goto, continue"],"query":"C+Programming+Operators+Conditional+Branching+if+else+switch+BTech"},{"title":"Unit III — Loops & Arrays","short":"Loops, Arrays, Strings, Structures","topics":["while, do-while, for loops — use cases and differences","Multiple loop variables, nested loops","Arrays: 1D and 2D, manipulation of elements","Character arrays and strings, string functions","Structures, unions, enumerated data types","Array of structures, passing arrays to functions"],"query":"C+Programming+Loops+Arrays+Strings+Structures+BTech+AKTU"},{"title":"Unit IV — Functions & Searching/Sorting","short":"Functions, Recursion, Algorithms","topics":["Functions: definition, types, call by value vs call by reference","Recursive functions — factorial, Fibonacci, binary search","Passing parameters to functions, scope of variables","Linear search and binary search implementation","Bubble sort, insertion sort, selection sort algorithms"],"query":"C+Programming+Functions+Recursion+Searching+Sorting+BTech+AKTU"},{"title":"Unit V — Pointers & File Handling","short":"Pointers, Dynamic Memory, Files","topics":["Pointers: declaration, initialization, pointer arithmetic","Dynamic memory allocation: malloc, calloc, realloc, free","String functions and pointer to strings","Self-referential structures, notion of linked list","File I/O: fopen, fclose, fread, fwrite, fprintf, fscanf"],"query":"C+Programming+Pointers+Dynamic+Memory+File+Handling+BTech+AKTU"}],"tips":[{"h":"Code Every Day","d":"<strong>Write at least one complete program daily</strong> — programming is a skill not theory, it only improves with practice."},{"h":"Trace on Paper","d":"<strong>Trace code by hand on paper</strong> step by step before running — builds deep understanding of execution flow."},{"h":"Master Pointers","d":"<strong>Draw memory diagrams for every pointer program</strong> — pointer questions are hardest and most rewarding in practicals."},{"h":"HackerRank Practice","d":"<strong>Solve 5 problems on HackerRank C domain daily</strong> — AKTU practical exams test live coding speed."}]},"BCS301":{"name":"Data Structure","importance":"Data Structures is THE most important subject of your entire CSE degree. Every software system — databases, operating systems, compilers, search engines — is built on efficient data structures. It is also the most heavily tested topic in every campus placement interview at Google, Amazon, Microsoft, and Flipkart.","whyMatters":["Most asked topic in all FAANG placement interviews","Operating systems use queues, trees, graphs internally","Databases use B-trees and hash tables for fast indexing","Compilers use stacks for expression parsing and code generation"],"units":[{"title":"Unit I — Intro, Arrays & Linked Lists","short":"Arrays, Linked Lists, Complexity","topics":["Basic Terminology, Algorithm efficiency, Time/Space Complexity","Big-O, Big-Theta, Big-Omega notations, Abstract Data Types (ADT)","Arrays: 1D/2D, Row/Column Major Order, Index formulae, Sparse matrices","Singly, Doubly, Circular Linked Lists — Insertion, Deletion, Traversal","Polynomial representation and arithmetic using linked lists"],"query":"Arrays+Linked+List+Data+Structures+AKTU+BTech+complexity+analysis"},{"title":"Unit II — Stack, Queue, Hashing & Searching","short":"Stack, Queue, Hash","topics":["Stack: Push/Pop, Array and Linked implementation","Prefix, Postfix, Infix conversions, Evaluation of postfix","Recursion: tail recursion, removal — Fibonacci, Hanoi, Binary Search","Queue: Circular Queue, Dequeue, Priority Queue","Searching: Sequential, Binary Search","Hashing: hash functions, collision resolution (chaining, open addressing)"],"query":"Stack+Queue+Hashing+Data+Structures+BTech+AKTU+infix+postfix"},{"title":"Unit III — Sorting Algorithms","short":"All Sorting Methods","topics":["Bubble sort, Selection sort, Insertion sort","Quick sort: partition algorithm, time complexity analysis","Merge sort: divide and conquer, stable sorting","Heap sort: building heap, heapify process","Radix sort: non-comparative sorting","Time/Space complexity comparison of all sorting algorithms"],"query":"Sorting+Algorithms+Quick+Merge+Heap+Radix+Sort+Data+Structures+BTech"},{"title":"Unit IV — Trees","short":"BST, AVL, Heap, Huffman","topics":["Binary Tree: array and linked representation","BST: insertion, deletion, search, modification","Traversals: Inorder, Preorder, Postorder — construction from traversals","Threaded Binary Trees, traversal of threaded trees","Huffman Coding using binary tree","AVL Tree, B-Tree, Binary Heaps — concept and basic operations"],"query":"Trees+BST+AVL+Huffman+Binary+Tree+Traversal+Data+Structures+BTech+AKTU"},{"title":"Unit V — Graphs","short":"BFS, DFS, Dijkstra, Kruskal","topics":["Graph terminology, directed and undirected graphs","Representations: Adjacency Matrix, Adjacency List","Graph Traversal: BFS and DFS algorithms","Connected Components, Spanning Trees","Minimum Cost Spanning Trees: Prim and Kruskal algorithms","Shortest Path: Warshall and Dijkstra algorithms"],"query":"Graphs+BFS+DFS+Dijkstra+Kruskal+Prim+Shortest+Path+Data+Structures+BTech"}],"tips":[{"h":"Draw Before Code","d":"<strong>Draw every data structure on paper</strong> before writing code — never code trees or graphs without a diagram."},{"h":"Implement from Scratch","d":"<strong>Code every structure without any library</strong> — AKTU practicals test raw implementation from memory."},{"h":"Complexity Always","d":"<strong>Write time AND space complexity</strong> for every algorithm — this alone can earn 5 easy marks in theory."},{"h":"PYQ Practice","d":"<strong>Solve AKTU DSA last 5 years papers</strong> — question patterns are very predictable for this subject."}]},"BCS302":{"name":"Computer Organization and Architecture","importance":"COA explains how a computer works at the hardware level — from logic gates to memory hierarchy. Understanding COA helps write faster, cache-friendly code, explains performance bottlenecks, and is a core GATE topic with high marks. Every embedded system developer needs this knowledge.","whyMatters":["Cache-friendly code runs 10x faster — COA explains why","Pipelining knowledge is used in compiler optimization","Core GATE topic — always 8-10 marks in exam","Foundation for embedded systems and hardware design"],"units":[{"title":"Unit I — Digital Systems & Processor Org","short":"Buses, Addressing Modes","topics":["Functional units and interconnections, Bus architecture, types of buses","Bus arbitration: daisy chain, centralized, distributed","Register, bus and memory transfer","Processor organization: general registers, stack organization","Addressing modes: immediate, direct, indirect, register, indexed"],"query":"Computer+Organization+Buses+Addressing+Modes+Processor+COA+BTech+AKTU"},{"title":"Unit II — ALU Design","short":"Adders, Booth Algorithm, IEEE 754","topics":["Look-ahead carry adders (faster addition)","Signed operand multiplication, Booth algorithm","Array multiplier design","Division and logic operations","Floating point arithmetic, ALU design","IEEE 754 Standard for floating point numbers"],"query":"ALU+Booth+Algorithm+IEEE+754+Floating+Point+COA+BTech+AKTU"},{"title":"Unit III — Control Unit & Pipelining","short":"Pipelining, RISC/CISC","topics":["Instruction types, formats, instruction cycles (fetch-decode-execute)","Micro-operations, execution of complete instruction","RISC vs CISC architecture comparison","Pipelining: stages, speedup, data/control/structural hazards","Hardwired vs Microprogrammed control","Horizontal vs Vertical microprogramming"],"query":"Pipelining+RISC+CISC+Control+Unit+Instruction+Cycle+COA+BTech+AKTU"},{"title":"Unit IV — Memory Organization","short":"Cache, Virtual Memory, Paging","topics":["Memory hierarchy: registers, cache, RAM, disk","Cache memory: concept, design, address mapping techniques","Direct, Associative, Set-Associative mapping — with numericals","Cache replacement policies: LRU, FIFO, Optimal","Virtual memory: demand paging, page replacement algorithms"],"query":"Cache+Memory+Virtual+Memory+Paging+COA+BTech+AKTU+direct+associative"},{"title":"Unit V — Input/Output & Interrupts","short":"I/O, DMA, Interrupts","topics":["Peripheral devices, I/O interface, I/O ports","Interrupts: hardware, types (maskable/non-maskable), ISR","Modes of data transfer: Programmed I/O, Interrupt-driven I/O, DMA","I/O channels and processors","Serial Communication: synchronous and asynchronous","Standard communication interfaces"],"query":"IO+DMA+Interrupts+Input+Output+Serial+Communication+COA+BTech+AKTU"}],"tips":[{"h":"Number Conversions","d":"<strong>Practice 10 binary/hex/octal conversion problems daily</strong> — always in AKTU COA exam for easy marks."},{"h":"Pipeline Diagrams","d":"<strong>Draw Gantt-style timing diagrams</strong> for pipelining numericals — standard question format in AKTU."},{"h":"Cache Mapping Problems","d":"<strong>Solve all 3 cache mapping techniques with numericals</strong> — direct, associative, set-associative appear every year."},{"h":"Morris Mano Book","d":"Follow <strong>Computer System Architecture by Morris Mano</strong> — perfectly aligned with AKTU COA syllabus."}]},"BCS303":{"name":"Discrete Structures & Theory of Logic","importance":"Discrete Structures is the mathematical backbone of computer science. Graph theory, logic, and set theory are used in algorithm design, network routing, database query optimization, compiler construction, and cryptography. Without it you cannot understand automata theory or advanced algorithms.","whyMatters":["Graph theory powers network routing (Dijkstra, Kruskal) algorithms","Logic is the basis of Boolean circuits and programming conditions","Set theory used in database relational algebra operations","Combinatorics used in algorithm complexity analysis and cryptography"],"units":[{"title":"Unit I — Set Theory & Relations","short":"Sets, POSET, Lattice","topics":["Sets: definition, types, operations, combination of sets","Relations: definition, operations, properties — reflexive, symmetric, transitive","Composite relations, equality, recursive definition, order of relations","POSET: partial order, Hasse diagrams","Lattices: bounded, complemented, distributed, modular, complete"],"query":"Set+Theory+Relations+POSET+Lattice+Hasse+Diagram+Discrete+Mathematics+BTech"},{"title":"Unit II — Functions & Boolean Algebra","short":"Functions, K-Map, Boolean","topics":["Functions: definition, classification (injective, surjective, bijective)","Operations on functions, growth of functions","Boolean Algebra: axioms, theorems, algebraic manipulation","Simplification of Boolean functions","Karnaugh Maps (K-Maps): 2, 3, 4 variable minimization"],"query":"Functions+Boolean+Algebra+Karnaugh+Map+Discrete+Mathematics+BTech+AKTU"},{"title":"Unit III — Propositional & Predicate Logic","short":"Logic, Truth Tables, Inference","topics":["Propositions, truth tables, tautology, satisfiability, contradiction","Algebra of propositions, rules of inference","Predicate Logic: first-order predicates, well-formed formulas","Universal (forall) and existential (exists) quantifiers","Inference theory of predicate logic, resolution"],"query":"Propositional+Logic+Predicate+Logic+Inference+Truth+Tables+Discrete+Math+BTech"},{"title":"Unit IV — Algebraic Structures","short":"Groups, Rings, Fields","topics":["Groups: definition, properties, subgroups, order, cyclic groups","Cosets, Lagrange theorem, normal subgroups","Permutation and symmetric groups, group homomorphisms","Rings: definition and elementary properties","Fields: definition and properties"],"query":"Groups+Rings+Fields+Algebraic+Structures+Discrete+Mathematics+BTech+AKTU"},{"title":"Unit V — Graph Theory & Combinatorics","short":"Graphs, Euler, Hamilton","topics":["Graph: definition, terminology, types of graphs","Multigraphs, bipartite graphs, planar graphs","Isomorphism and homeomorphism of graphs","Euler paths/circuits and Hamiltonian paths","Graph coloring, chromatic number","Counting techniques, Pigeonhole Principle, combinatorics"],"query":"Graph+Theory+Euler+Hamiltonian+Pigeonhole+Combinatorics+Discrete+Maths+BTech"}],"tips":[{"h":"Truth Tables","d":"<strong>Practice building truth tables quickly</strong> — simple but always in every AKTU Discrete exam for easy marks."},{"h":"K-Map Practice","d":"<strong>Master 3 and 4-variable K-Map minimization</strong> — always appears in theory and practical both."},{"h":"Graph Problems","d":"<strong>Solve Euler path, Hamiltonian, spanning tree problems</strong> from PYQs — guaranteed question every year."},{"h":"Kenneth Rosen Book","d":"Follow <strong>Rosen Discrete Mathematics & Its Applications</strong> — the AKTU standard reference for this subject."}]},"BCS401":{"name":"Operating System","importance":"Operating Systems is the software bridge between programs and hardware. Every developer must understand OS to write efficient applications. Process management, memory management, and file systems directly impact application performance. OS is also one of the most tested topics in FAANG technical interviews.","whyMatters":["Process and thread management used in every modern application","Memory management essential for writing efficient, bug-free code","Most asked topic in FAANG technical and system design interviews","Cloud computing and virtualization are OS concepts at scale"],"units":[{"title":"Unit I — Process Management","short":"Processes, Threads, IPC","topics":["Process: concept, states (new, ready, running, waiting, terminated)","Process Control Block (PCB), process creation and termination","Threads: user-level vs kernel-level, multithreading models","Inter-Process Communication (IPC): shared memory, message passing","Producer-Consumer problem, Race condition basics"],"query":"Process+Management+PCB+Threads+IPC+Operating+System+BTech+AKTU"},{"title":"Unit II — CPU Scheduling","short":"FCFS, SJF, Round Robin, Gantt","topics":["Scheduling criteria: CPU utilization, throughput, turnaround, waiting time","FCFS: first-come first-served scheduling, Gantt chart","SJF/SRTF: shortest job first — preemptive and non-preemptive","Round Robin: time quantum, context switching, turnaround calculation","Priority Scheduling, Multilevel Queue and Feedback Queue"],"query":"CPU+Scheduling+FCFS+SJF+Round+Robin+Priority+OS+BTech+Gantt+chart+AKTU"},{"title":"Unit III — Synchronization & Deadlock","short":"Semaphore, Banker Algorithm","topics":["Critical section problem, mutual exclusion requirements","Mutex locks, semaphores (binary and counting)","Classic problems: Producer-Consumer, Readers-Writers, Dining Philosophers","Deadlock: four Coffman necessary conditions","Deadlock prevention, avoidance — Banker algorithm","Deadlock detection and recovery strategies"],"query":"Synchronization+Deadlock+Semaphore+Banker+Algorithm+OS+BTech+AKTU+dining"},{"title":"Unit IV — Memory Management","short":"Paging, Segmentation, TLB","topics":["Contiguous allocation: fixed/variable partitioning, fragmentation types","Paging: logical vs physical address, page table, TLB","Segmentation: segment table, protection bits","Combined paging-segmentation","Memory allocation algorithms: first-fit, best-fit, worst-fit"],"query":"Memory+Management+Paging+Segmentation+TLB+Page+Table+OS+BTech+AKTU"},{"title":"Unit V — Virtual Memory, File Systems & Disk","short":"Virtual Memory, LRU, FIFO","topics":["Virtual memory: demand paging, page fault handling","Page replacement: FIFO, LRU, Optimal — Belady anomaly","Thrashing: concept, causes, and prevention","File system: file concept, access methods, directory structure","File allocation: contiguous, linked, indexed methods","Disk scheduling: FCFS, SSTF, SCAN, C-SCAN, LOOK"],"query":"Virtual+Memory+Page+Replacement+LRU+FIFO+File+System+Disk+Scheduling+OS"}],"tips":[{"h":"Gantt Charts Daily","d":"<strong>Solve 3 Gantt chart problems daily</strong> (FCFS, SJF, Round Robin) — guaranteed 15-20 marks in AKTU OS exam."},{"h":"Banker Algorithm Steps","d":"<strong>Memorize and practice Banker algorithm step-by-step</strong> — appears in every AKTU OS paper."},{"h":"Page Replacement Numericals","d":"<strong>Solve LRU, FIFO, Optimal page replacement with a page string</strong> — 10 marks question every year."},{"h":"Galvin Book","d":"Follow <strong>Operating System Concepts by Galvin (Dinosaur Book)</strong> — perfectly matches AKTU OS syllabus."}]},"BCS402":{"name":"Theory of Automata & Formal Languages","importance":"Theory of Automata answers the fundamental question of CS: what can computers solve and what cannot they solve? Regular expressions used in every programming language and IDE come from automata. Every compiler parser is a pushdown automaton. This subject is also a core GATE topic.","whyMatters":["Regular expressions (grep, search) come directly from finite automata","Compiler lexical analyzer is built on DFA/NFA concepts","Parser (syntax analyzer) is a pushdown automaton","Core GATE topic — always 8-10 marks"],"units":[{"title":"Unit I — Finite Automata","short":"DFA, NFA, Conversion, Minimization","topics":["DFA: formal definition, transition diagram, construction for given languages","NFA: formal definition, non-determinism","Epsilon-NFA: epsilon-closure, epsilon-transitions","NFA to DFA conversion (subset construction method)","Minimization of DFA (table-filling/equivalence method)"],"query":"DFA+NFA+Finite+Automata+Conversion+Minimization+TOC+BTech+AKTU"},{"title":"Unit II — Regular Expressions & Pumping Lemma","short":"RE, Arden Theorem","topics":["Regular expressions: operators (union, concatenation, Kleene star)","RE to FA conversion and FA to RE (Arden theorem)","Properties of Regular Languages: closure properties","Pumping Lemma for Regular Languages","Proving languages are NOT regular using Pumping Lemma"],"query":"Regular+Expressions+Arden+Theorem+Pumping+Lemma+TOC+BTech+AKTU"},{"title":"Unit III — Context Free Grammars","short":"CFG, CNF, GNF, Ambiguity","topics":["CFG: formal definition, derivations, parse trees","Leftmost and rightmost derivations","Ambiguous grammars: definition, examples","Simplification: removing useless symbols, epsilon, unit productions","Chomsky Normal Form (CNF), Greibach Normal Form (GNF)"],"query":"Context+Free+Grammar+CFG+CNF+GNF+Parse+Tree+TOC+BTech+AKTU"},{"title":"Unit IV — Pushdown Automata","short":"PDA, DPDA, CFL Pumping Lemma","topics":["PDA: formal definition, stack operations, configuration","PDA construction for given CFLs","Deterministic PDA (DPDA) vs Non-deterministic PDA","Equivalence of PDA and CFG","Pumping Lemma for Context-Free Languages"],"query":"Pushdown+Automata+PDA+Context+Free+Language+TOC+BTech+AKTU"},{"title":"Unit V — Turing Machines & Decidability","short":"Turing Machine, Halting Problem","topics":["Turing Machine: formal definition, transition function, configurations","TM construction for simple languages","Variants: multi-tape TM, non-deterministic TM","Church-Turing Thesis","Decidable and Undecidable problems","Halting problem (proof of undecidability)"],"query":"Turing+Machine+Decidability+Halting+Problem+TOC+BTech+AKTU"}],"tips":[{"h":"DFA Every Day","d":"<strong>Draw 2 new DFAs from scratch daily</strong> — construction questions are the highest marks in AKTU TOC exam."},{"h":"Pumping Lemma Template","d":"<strong>Learn the exact 5-step pumping lemma proof format</strong> — informal proofs get no marks in AKTU."},{"h":"NFA to DFA","d":"<strong>Practice NFA to DFA conversion 3 times per week</strong> — a guaranteed question in every AKTU TOC paper."},{"h":"Neso Academy Videos","d":"<strong>Watch Neso Academy TOC complete playlist</strong> — clearest explanations perfectly aligned with AKTU syllabus."}]},"BCS403":{"name":"Object Oriented Programming with Java","importance":"Java OOP introduces the programming paradigm that powers modern software. Java runs on 3 billion devices — Android apps, enterprise backends, banking systems. OOP principles (encapsulation, inheritance, polymorphism, abstraction) are foundational concepts used in every modern language including Python and Kotlin.","whyMatters":["Java powers Android development and most enterprise applications","OOP concepts apply directly to Python, C++, Kotlin, C# too","Design patterns from OOP asked in system design interviews","Spring Boot (Java) is the #1 enterprise backend framework globally"],"units":[{"title":"Unit I — Java Basics & OOP Intro","short":"Classes, Objects, Constructors","topics":["Java history, JVM, JDK, JRE, bytecode compilation","Data types, variables, operators, control flow in Java","Classes, objects, access modifiers (public, private, protected)","Constructors: default, parameterized, copy constructor, overloading","this keyword, static members, instance vs class variables","Garbage collection in Java"],"query":"Java+Classes+Objects+Constructors+OOP+BTech+AKTU+basics"},{"title":"Unit II — Inheritance & Polymorphism","short":"Inheritance, Method Overriding","topics":["Inheritance types: single, multilevel, hierarchical","super keyword for parent constructor and method call","Method overloading (compile-time polymorphism)","Method overriding (runtime polymorphism), @Override annotation","final keyword: final class, final method, final variable","Object class and its methods (toString, equals, hashCode)"],"query":"Java+Inheritance+Polymorphism+Method+Overriding+super+BTech+AKTU"},{"title":"Unit III — Abstraction & Interfaces","short":"Abstract Classes, Interfaces","topics":["Abstract classes: abstract methods, partial implementation rules","Interfaces: definition, implementing multiple interfaces","Default and static methods in interfaces (Java 8+)","Abstract class vs Interface — when to use which","Packages: creating, importing, access protection levels","Java API packages: java.lang, java.util, java.io"],"query":"Java+Abstract+Class+Interface+Package+OOP+BTech+AKTU"},{"title":"Unit IV — Exception Handling & Collections","short":"Exceptions, Generics, Collections","topics":["Exception hierarchy: Throwable, Exception, Error classes","try-catch-finally, multiple catch blocks, nested try","throw and throws keywords, checked vs unchecked exceptions","Custom exception classes","Generics: generic methods and generic classes","Collections: List, Set, Map, ArrayList, HashMap, Iterator"],"query":"Java+Exception+Handling+Generics+Collections+ArrayList+HashMap+BTech+AKTU"},{"title":"Unit V — Multithreading & File I/O","short":"Threads, Synchronization, Files","topics":["Thread lifecycle: new, runnable, running, blocked, terminated","Creating threads: extending Thread class and implementing Runnable","Thread synchronization: synchronized keyword, monitors, locks","Deadlock in threads, inter-thread communication (wait/notify)","File I/O: FileInputStream, FileOutputStream, BufferedReader, Writer","Serialization and deserialization of objects"],"query":"Java+Multithreading+Thread+Synchronization+File+IO+Serialization+BTech+AKTU"}],"tips":[{"h":"Implement All OOP Pillars","d":"<strong>Code all 4 OOP pillars with real examples</strong> — bank account (encapsulation), shapes (inheritance + polymorphism)."},{"h":"UML Class Diagrams","d":"<strong>Draw UML class diagrams</strong> for every program — examiners give extra marks for correct diagrams."},{"h":"Exception Programs","d":"<strong>Write programs for every exception type</strong> — custom exceptions are tested in practicals every year."},{"h":"Mini Project","d":"Build a <strong>Library or Student Management System</strong> applying all OOP concepts — perfect practical exam prep."}]},"BCS501":{"name":"Database Management System","importance":"DBMS powers every application that stores data — from Instagram to banking. SQL is the most in-demand skill in all software job listings. DBMS teaches database design, querying, normalization, and transaction management — all essential for backend development and data engineering careers.","whyMatters":["SQL is the #1 most in-demand technical skill in job listings","Every web/mobile application uses a database backend","Data engineering and analytics careers start with DBMS","Indexing and query optimization make applications 100x faster"],"units":[{"title":"Unit I — ER Model & Database Architecture","short":"ER Diagrams, Keys","topics":["Database vs File System, DBMS architecture overview","Data Independence: logical and physical","ER Model: entities, attributes, relationships, ER diagrams","Keys: super key, candidate key, primary key","Generalization, aggregation, reduction of ER to tables","Extended ER model, relationships of higher degree"],"query":"ER+Diagram+Database+Architecture+DBMS+BTech+AKTU+entity+relationship"},{"title":"Unit II — Relational Model & SQL","short":"SQL, Joins, Triggers","topics":["Relational model: integrity constraints, entity and referential integrity","Relational Algebra: selection, projection, join, union, intersection","Tuple and Domain Relational Calculus","SQL: DDL, DML, DCL, aggregate functions, joins, subqueries","Views, indexes, cursors, triggers, procedures in SQL/PL-SQL"],"query":"SQL+Joins+Triggers+Relational+Algebra+DBMS+BTech+AKTU+queries"},{"title":"Unit III — Database Normalization","short":"1NF, 2NF, 3NF, BCNF","topics":["Functional dependencies: definition, types, finding FDs","Normal Forms: 1NF, 2NF, 3NF — definitions and examples","BCNF: Boyce-Codd Normal Form","Inclusion dependence, lossless join decompositions","Normalization using FD, MVD, and JDs"],"query":"Normalization+1NF+2NF+3NF+BCNF+Functional+Dependency+DBMS+BTech+AKTU"},{"title":"Unit IV — Transaction Processing","short":"ACID, Serializability, Deadlock","topics":["Transaction concepts: ACID properties","Testing for serializability, conflict serializability","Recoverability, recovery from transaction failures","Log-based recovery, checkpoints","Distributed database: data storage, concurrency control"],"query":"Transaction+ACID+Serializability+Recovery+Log+DBMS+BTech+AKTU"},{"title":"Unit V — Concurrency Control","short":"Locking, Timestamps, Oracle Case","topics":["Concurrency control: need and problems (lost update, dirty read)","Locking techniques: 2-Phase Locking (2PL) — strict and conservative","Timestamp ordering protocols for concurrency control","Validation-based protocol, Multiple granularity","Multi-version concurrency control, Case study of Oracle"],"query":"Concurrency+Control+Locking+2PL+Timestamp+DBMS+BTech+AKTU"}],"tips":[{"h":"SQL Every Day","d":"<strong>Write 5 SQL queries daily</strong> on HackerRank SQL or SQLZoo — SQL is a skill that only improves with daily practice."},{"h":"ER Diagram Practice","d":"<strong>Draw ER diagrams for real scenarios</strong> — hospital, library, airline — asked in every AKTU DBMS exam."},{"h":"Normalization Steps","d":"<strong>Show all normalization steps clearly</strong>: find FDs, identify normal form, decompose — step-by-step gets full marks."},{"h":"Transaction Numericals","d":"<strong>Practice serializability and 2PL lock problems</strong> — appear as 10-mark questions in every AKTU paper."}]},"BCS502":{"name":"Web Technology","importance":"Web Technology is the gateway to the most in-demand developer career — full-stack web development. Every company needs web developers. HTML, CSS, JavaScript, Servlets, and JSP form the basis of every website and web application. This directly leads to careers in frontend, backend, and full-stack development.","whyMatters":["Web development is the highest-demand tech skill globally","Freelancing opportunities start from basic HTML/CSS/JS skills","React, Angular, Node.js all build on JS concepts from this course","Full-stack development is the most commonly hired developer profile"],"units":[{"title":"Unit I — HTML, XML & Web Basics","short":"HTML5, XML, DTD, DOM, SAX","topics":["Introduction to web development, history of internet and web","Protocols: HTTP, HTTPS, FTP, TCP/IP","HTML: lists, tables, images, frames, forms, semantic elements","XML: Document Type Definition (DTD), XML Schema","Object Models: DOM and SAX processors, presenting XML"],"query":"HTML+XML+DTD+DOM+SAX+Web+Technology+BTech+AKTU"},{"title":"Unit II — CSS (Basics & Advanced)","short":"CSS, Box Model, Layout","topics":["CSS: creating style sheets, CSS properties","Styling: background, text, fonts, colors","Box Model: border, padding, margin properties","Block elements and objects, lists and tables in CSS","Advanced CSS: grouping, display, positioning, float, pseudo-class","Navigation bar, Image Sprites, Page layout design"],"query":"CSS+Box+Model+Layout+Flexbox+Web+Technology+BTech+AKTU"},{"title":"Unit III — JavaScript & Networking","short":"JavaScript, DOM, AJAX","topics":["JavaScript: variables, functions, objects, statements","DOM manipulation with JavaScript, event handling","Introduction to AJAX: XMLHttpRequest, asynchronous requests","Networking: InetAddress, Factory Methods, TCP/IP sockets","URL, URLConnection, Server Sockets, Datagram"],"query":"JavaScript+DOM+AJAX+Web+Technology+BTech+AKTU"},{"title":"Unit IV — Enterprise Java & Node.js","short":"JavaBeans, Node.js, MongoDB","topics":["Enterprise JavaBeans: stateful/stateless session beans, entity beans","Node.js: setup, REPL, NPM, callbacks, events","Express framework, RESTful APIs with Node.js","MongoDB with Node.js: CRUD operations, aggregation, sorting"],"query":"NodeJS+MongoDB+JavaBeans+REST+API+Web+Technology+BTech+AKTU"},{"title":"Unit V — Servlets & JSP","short":"Servlets, Session, JSP, Custom Tags","topics":["Servlets: architecture, lifecycle (init, service, destroy)","Handling HTTP GET and POST requests","Session tracking: cookies and HttpSession API","JSP: overview, implicit objects, scriptlets, directives","Standard actions in JSP, Custom Tag Libraries (JSTL)"],"query":"Servlets+JSP+Session+Cookies+Web+Technology+BTech+AKTU"}],"tips":[{"h":"Build Real Projects","d":"<strong>Build a complete website applying every concept</strong> — portfolio, blog, student form — best practical preparation."},{"h":"JavaScript Daily","d":"<strong>Practice JavaScript DOM events and form validation daily</strong> — JS is tested hardest in AKTU web tech practicals."},{"h":"Run Servlets Locally","d":"<strong>Set up Apache Tomcat and run Servlet/JSP examples</strong> locally — practical exams test live coding."},{"h":"CSS Layouts","d":"<strong>Learn CSS Flexbox and Grid for responsive layouts</strong> — modern layout techniques impress examiners."}]},"BCS503":{"name":"Design and Analysis of Algorithm","importance":"DAA is THE subject for cracking placements at top tech companies. Every technical interview tests your ability to design efficient algorithms. Understanding time/space complexity, dynamic programming, and graph algorithms directly determines your success in Google, Amazon, Microsoft, and Flipkart interviews.","whyMatters":["Every technical interview at top companies tests algorithm design","Dynamic programming optimizes GPS routing, compiler optimization","Greedy algorithms power network routing and scheduling systems","Understanding NP-completeness defines limits of what software can solve"],"units":[{"title":"Unit I — Complexity & Advanced Sorting","short":"Big-O, Shell/Quick/Merge/Heap Sort","topics":["Algorithm analysis: time and space complexity, growth of functions","Performance measurements, sorting comparison","Shell Sort, Quick Sort, Merge Sort, Heap Sort — detailed analysis","Comparison of sorting algorithms: stability, adaptability, complexity","Sorting in linear time: Counting Sort, Radix Sort concepts"],"query":"Algorithm+Complexity+Big+O+Sorting+Quick+Merge+Heap+DAA+BTech+AKTU"},{"title":"Unit II — Advanced Data Structures","short":"Red-Black Trees, B-Trees, Heaps","topics":["Red-Black Trees: properties, rotations, insertion, deletion","B-Trees: properties, insertion and deletion operations","Binomial Heaps: structure and operations","Fibonacci Heaps: structure and amortized complexity","Tries: structure, insertion, search applications","Skip Lists: structure and probabilistic analysis"],"query":"Red+Black+Trees+B+Trees+Fibonacci+Heaps+DAA+BTech+AKTU"},{"title":"Unit III — Divide & Conquer + Greedy","short":"Divide Conquer, Dijkstra, Kruskal","topics":["Divide and Conquer: sorting, matrix multiplication, convex hull","Greedy: optimal reliability allocation, fractional knapsack","Minimum Spanning Trees: Prim and Kruskal algorithms","Single Source Shortest Paths: Dijkstra algorithm","Bellman-Ford algorithm for negative weights"],"query":"Divide+Conquer+Greedy+Dijkstra+Kruskal+Prim+Bellman+Ford+DAA+BTech"},{"title":"Unit IV — Dynamic Programming & Backtracking","short":"DP, 0/1 Knapsack, TSP","topics":["Dynamic Programming: 0/1 Knapsack problem","All Pairs Shortest Paths: Floyd-Warshall algorithm","Resource Allocation Problem using DP","Backtracking: N-Queen problem, Graph Coloring","Branch and Bound: Travelling Salesman Problem (TSP), Hamiltonian Cycles","Sum of Subsets problem"],"query":"Dynamic+Programming+Knapsack+Floyd+Warshall+Backtracking+DAA+BTech+AKTU"},{"title":"Unit V — NP-Completeness & Approximation","short":"NP, Approximation, String Matching","topics":["Algebraic Computation, Fast Fourier Transform (FFT)","String Matching: naive, KMP, Rabin-Karp algorithms","Theory of NP-Completeness: P vs NP, NP-Hard, NP-Complete","Polynomial time reductions","Approximation Algorithms: vertex cover, traveling salesman","Randomized Algorithms: basics and applications"],"query":"NP+Completeness+Approximation+Algorithm+String+Matching+DAA+BTech+AKTU"}],"tips":[{"h":"Complexity Always","d":"<strong>Write time AND space complexity</strong> for every algorithm — this alone earns easy 5 marks in AKTU DAA theory."},{"h":"DP 5 Core Patterns","d":"<strong>Master 5 DP patterns: Knapsack, LCS, Matrix Chain, Coin Change, Floyd-Warshall</strong> — covers 80% of DP questions."},{"h":"Greedy Proofs","d":"<strong>Write exchange argument proofs for greedy algorithms</strong> — AKTU theory exams ask for correctness justification."},{"h":"LeetCode Medium","d":"<strong>Solve 50 LeetCode Medium problems topic-wise</strong> — directly prepares for company placement interviews."}]},"BCS601":{"name":"Software Engineering","importance":"Software Engineering teaches how real software is built professionally in teams. Without SE principles, codebases become unmaintainable. Every software job involves SDLC, requirement engineering, UML design, and testing. This is what separates a professional developer from a hobbyist coder.","whyMatters":["Every professional software project follows SE SDLC principles","Agile and Scrum (from SE) used in 90%+ of IT companies worldwide","UML is the universal software design language across all companies","Software testing prevents failures that cost companies billions"],"units":[{"title":"Unit I — Introduction & SDLC Models","short":"Waterfall, Spiral, Agile","topics":["Software characteristics, software crisis, software engineering processes","Software Quality Attributes","Waterfall Model: phases and limitations","Prototype Model, Spiral Model","Evolutionary Development Models, Iterative Enhancement Models"],"query":"SDLC+Waterfall+Spiral+Agile+Software+Engineering+BTech+AKTU"},{"title":"Unit II — SRS & Software Quality Assurance","short":"SRS, DFD, ER, CMM","topics":["Requirements engineering: elicitation, analysis, documentation","Feasibility study, Information modeling","Data Flow Diagrams (DFD), ER Diagrams, Decision Tables","SRS Document as per IEEE standards","SQA: Verification and Validation, ISO 9000, SEI-CMM Model"],"query":"SRS+DFD+Software+Requirements+IEEE+CMM+Software+Engineering+BTech+AKTU"},{"title":"Unit III — Software Design & Metrics","short":"Modular Design, Coupling, Cohesion","topics":["Architectural design, modularization, design structure charts","Pseudo codes, flow charts","Coupling: types (content, control, data) and Cohesion: types","Design strategies: Function-Oriented, Object-Oriented","Halstead Software Science, Function Point (FP) measures","Cyclomatic Complexity, Control Flow Graphs"],"query":"Software+Design+Coupling+Cohesion+Function+Point+Cyclomatic+BTech+AKTU"},{"title":"Unit IV — Software Testing","short":"Unit Test, Black Box, White Box","topics":["Testing objectives, Unit Testing, Integration Testing","Acceptance Testing, Regression Testing","Bottom-Up and Top-Down testing strategies, Test Stubs, Drivers","White Box (Structural) Testing: path testing, basis path","Black Box (Functional) Testing: equivalence partitioning, boundary value","Alpha and Beta testing, Static testing: code inspection, walkthroughs"],"query":"Software+Testing+Black+Box+White+Box+Unit+Integration+BTech+AKTU"},{"title":"Unit V — Maintenance & Project Management","short":"COCOMO, Risk, Configuration","topics":["Software maintenance: preventive, corrective, perfective","Software Re-engineering and Reverse Engineering","Configuration Management, Version Control, CASE Tools","Project estimation: COCOMO model, Resource Allocation Models","Software Risk Analysis and Management"],"query":"COCOMO+Risk+Analysis+Software+Maintenance+Project+Management+BTech+AKTU"}],"tips":[{"h":"All UML Diagrams","d":"<strong>Practice all 9 UML diagram types</strong> — use case, class, sequence, activity are most common in AKTU SE paper."},{"h":"SDLC Comparison Table","d":"<strong>Make a comparison table of all SDLC models</strong> — \"compare Waterfall vs Agile\" is asked every year."},{"h":"COCOMO Formula","d":"<strong>Memorize and practice COCOMO estimation formula</strong> — numerical problems appear in every AKTU exam."},{"h":"Testing Types Table","d":"<strong>Know every testing type, when to use it, and who does it</strong> — comparison questions are high-value in theory."}]},"BCS602":{"name":"Compiler Design","importance":"Compiler Design explains how programs are translated from high-level language to machine code. Every IDE, code editor, and interpreter you use is built on compiler principles. Understanding compilers makes you a better programmer because you understand exactly how your code is processed and optimized.","whyMatters":["IDE syntax highlighting uses lexical analysis (DFA)","Regular expressions in all programming come from this subject","Understanding compilation helps write more optimizable code","Language interpreters (Python, JS engines) use all compiler phases"],"units":[{"title":"Unit I — Lexical Analysis & Parsing Intro","short":"LEX, YACC, CFG, BNF","topics":["Phases and passes of compiler, Bootstrapping","Finite state machines and regular expressions for lexical analysis","Lexical analyzer generator: LEX compiler","Formal grammars, BNF notation, ambiguity","Context Free Grammars: derivations and parse trees, capabilities of CFG"],"query":"Lexical+Analysis+LEX+YACC+CFG+BNF+Compiler+Design+BTech+AKTU"},{"title":"Unit II — Parsing Techniques","short":"LR, SLR, LALR, LL(1)","topics":["Basic parsing: shift-reduce parsing, operator precedence parsing","Top-down parsing, predictive parsers","LR parsers: canonical LR(0) items","SLR parsing tables construction","Canonical LR and LALR parsing tables construction","Using ambiguous grammars, automatic parser generator"],"query":"LR+SLR+LALR+LL1+Parsing+Compiler+Design+BTech+AKTU"},{"title":"Unit III — Syntax-Directed Translation","short":"SDT, Three-Address Code","topics":["Syntax-directed translation schemes and implementation","Intermediate code: postfix notation, parse trees, syntax trees","Three-address code: quadruples and triples","Translation of assignment statements and Boolean expressions","Statements that alter flow of control (if, while)","Array references, procedure calls in expressions"],"query":"Syntax+Directed+Translation+Three+Address+Code+Compiler+Design+BTech"},{"title":"Unit IV — Symbol Tables & Runtime","short":"Symbol Table, Stack Allocation","topics":["Data structures for symbol tables: hash tables, trees","Representing scope information","Runtime administration: simple stack allocation","Storage allocation in block-structured languages","Error detection and recovery: lexical, syntactic, semantic errors"],"query":"Symbol+Table+Runtime+Storage+Allocation+Error+Recovery+Compiler+Design+BTech"},{"title":"Unit V — Code Generation & Optimization","short":"Code Gen, Loop Optimization","topics":["Code generation: design issues, target language selection","Addresses in target code, Basic blocks and flow graphs","Optimization of basic blocks, simple code generator","Machine-independent optimizations","Loop optimization: code motion, strength reduction, induction variables","DAG representation, Global Data-Flow analysis"],"query":"Code+Generation+Optimization+Loop+DAG+Compiler+Design+BTech+AKTU"}],"tips":[{"h":"FIRST & FOLLOW Daily","d":"<strong>Practice computing FIRST and FOLLOW sets for 3 grammars daily</strong> — every AKTU Compiler exam has this question."},{"h":"Parsing Tables","d":"<strong>Construct LL(1) and SLR parsing tables step-by-step</strong> clearly — marks given for each correct step."},{"h":"Grammar Derivations","d":"<strong>Practice leftmost and rightmost derivations</strong> and drawing parse trees — common 5-mark questions."},{"h":"Dragon Book","d":"<strong>Read Aho, Sethi & Ullman (Dragon Book) chapter summaries</strong> — perfectly aligned with AKTU Compiler Design syllabus."}]},"BCS603":{"name":"Computer Networks","importance":"Computer Networks explains how the internet works. Every web app, API call, video stream, and cloud service depends on networking. Networking is essential for cloud computing, cybersecurity, backend development, and DevOps. It is also the most asked topic in system design interviews at top companies.","whyMatters":["Internet and all web applications run on TCP/IP networking protocols","Cloud computing and DevOps require deep networking knowledge","Cybersecurity is fundamentally about understanding network attacks","System design interviews always ask about load balancers, DNS, CDN"],"units":[{"title":"Unit I — OSI Model, TCP/IP & Physical Layer","short":"OSI Layers, Media, Encoding","topics":["Goals and applications of networks, categories of networks","OSI Reference Model: 7 layers, functions of each layer","TCP/IP protocol suite: 5-layer model comparison","Network devices: hub, switch, router, gateway, bridge","Physical Layer: transmission media, signal encoding, multiplexing, switching"],"query":"OSI+Model+TCP+IP+Physical+Layer+Computer+Networks+BTech+AKTU"},{"title":"Unit II — Data Link Layer & MAC","short":"Framing, CRC, Sliding Window","topics":["Framing: character count, flag bytes, bit stuffing","Error Detection: CRC (Cyclic Redundancy Check), checksum, parity","Error Correction: Hamming code","Flow Control: Elementary protocols, Sliding Window protocols (Go-Back-N, SR)","Medium Access Control: channel allocation, multiple access protocols","LAN standards, learning bridges, spanning tree algorithm"],"query":"Data+Link+Layer+CRC+Sliding+Window+Flow+Control+Computer+Networks+BTech"},{"title":"Unit III — Network Layer","short":"IP Addressing, Subnetting, Routing","topics":["Point-to-point networks, logical addressing (IPv4)","Basic internetworking: IP, CIDR, ARP, RARP, DHCP, ICMP","Subnetting: variable-length subnet masking (VLSM) — numericals","Routing algorithms: Distance Vector, Link State","Routing protocols: OSPF, BGP","Congestion control algorithms, IPv6 introduction"],"query":"IP+Addressing+Subnetting+Routing+OSPF+Computer+Networks+BTech+AKTU"},{"title":"Unit IV — Transport Layer","short":"TCP, UDP, Congestion Control","topics":["Process-to-process delivery, port numbers","UDP: connectionless, stateless — when to use it","TCP: connection-oriented, 3-way handshake, 4-way termination","TCP flow control: sliding window, credit-based","TCP congestion control: slow start, congestion avoidance, fast retransmit","Quality of Service (QoS)"],"query":"TCP+UDP+Transport+Layer+Congestion+Control+Computer+Networks+BTech"},{"title":"Unit V — Application Layer & Security","short":"HTTP, DNS, FTP, Cryptography","topics":["DNS: domain name resolution, hierarchy, resource records","HTTP/HTTPS: request/response, methods, status codes","Electronic Mail: SMTP, POP3, IMAP protocols","FTP, Telnet, Remote Login, SNMP","Data compression techniques","Cryptography basics: symmetric, asymmetric, digital signatures"],"query":"HTTP+DNS+FTP+SMTP+Application+Layer+Computer+Networks+BTech+AKTU"}],"tips":[{"h":"Subnetting Every Day","d":"<strong>Solve 5 IP subnetting problems daily</strong> — subnetting numericals are in every AKTU CN exam for guaranteed marks."},{"h":"Protocol Table","d":"<strong>Make a table: Protocol | Layer | Port | Purpose</strong> — memorize 15+ protocols for theory questions."},{"h":"CRC Numericals","d":"<strong>Practice CRC calculation step-by-step</strong> — data link layer numerical appears in every AKTU CN paper."},{"h":"Forouzan Book","d":"Follow <strong>Forouzan Data Communication and Networking</strong> — perfectly aligned with AKTU CN syllabus."}]},"BCS701":{"name":"Artificial Intelligence","importance":"Artificial Intelligence is the most transformative technology of the 21st century. AI powers search engines, recommendation systems, voice assistants, self-driving cars, and medical diagnosis. Understanding AI fundamentals positions you at the cutting edge and opens doors to the highest-paying jobs in the entire tech industry.","whyMatters":["AI/ML engineers are the highest-paid developers globally (avg 15-30 LPA+)","AI powers Google Search, Netflix, Spotify, Siri, Alexa, ChatGPT","Every industry — healthcare, finance, education — is being transformed by AI","Explainable AI (XAI) is the new requirement for deploying AI systems responsibly"],"units":[{"title":"Unit I — AI Intro & Intelligent Agents","short":"AI Basics, Agent Architecture","topics":["Definition and scope of AI, history and applications","Characteristics of Intelligent Agents, types of agents and environments","Agent architecture: simple reflex, model-based, goal-based, utility-based","Problem-Solving Approach: formulation, state space representation","Example AI problems: 8-puzzle, missionaries, water jug"],"query":"Artificial+Intelligence+Introduction+Intelligent+Agents+BTech+AKTU"},{"title":"Unit II — Search Strategies & Game Playing","short":"BFS, A*, Minimax, Alpha-Beta","topics":["Uninformed Search: BFS, DFS, Iterative Deepening Search","Informed Search: Greedy Best-First Search, A* Algorithm","Heuristics: admissibility, consistency, design principles","Hill Climbing, Simulated Annealing, Constraint Satisfaction Problems","Game Playing: Min-Max algorithm, Alpha-Beta Pruning","Stochastic and Partially Observable Games"],"query":"A+Star+Search+Heuristics+Minimax+Alpha+Beta+AI+BTech+AKTU"},{"title":"Unit III — Knowledge Representation & Reasoning","short":"Logic, Prolog, Chaining","topics":["Propositional Logic: syntax, semantics, inference","First Order Logic: predicates, quantifiers, unification","Knowledge-based agents: Wumpus world example","Logic Programming using Prolog","Forward and Backward Chaining","Resolution, Ontological Engineering"],"query":"Knowledge+Representation+First+Order+Logic+Prolog+AI+BTech+AKTU"},{"title":"Unit IV — Uncertainty & Learning","short":"Bayes Rule, Neural Networks, ML","topics":["Introduction to uncertainty and probabilistic reasoning","Bayes Rule, Bayesian Networks","Fuzzy Logic: handling imprecision and uncertainty","Neural Networks basics: Perceptron, Backpropagation (introductory)","Fundamentals of Machine Learning in AI context","Supervised and unsupervised learning introduction"],"query":"Bayesian+Networks+Fuzzy+Logic+Neural+Networks+Machine+Learning+AI+BTech"},{"title":"Unit V — AI Applications & Multi-Agent Systems","short":"NLP, Robotics, XAI","topics":["Natural Language Processing: machine translation, information retrieval","Robotics: perception, planning, and motion","Speech Recognition fundamentals","Software Agents: architecture, communication, trust","Multi-Agent Negotiation and Reputation systems","Explainable AI (XAI): interpretability, techniques, trust, case studies"],"query":"NLP+Robotics+Multi+Agent+Systems+XAI+Explainable+AI+BTech+AKTU"}],"tips":[{"h":"A* Search Problems","d":"<strong>Solve A* search with heuristic tables and admissibility check</strong> — most common numerical in AKTU AI exam."},{"h":"Python for AI","d":"<strong>Start learning Python with NumPy, Pandas, Scikit-learn</strong> — language of AI industry, expected in practicals."},{"h":"Neural Network Math","d":"<strong>Understand backpropagation mathematically step-by-step</strong> — derivation is asked in AKTU AI theory."},{"h":"Russell & Norvig AIMA","d":"Read <strong>AIMA 4th Edition by Russell & Norvig</strong> — the definitive AI textbook aligned to AKTU."}]},"BCS070":{"name":"Internet of Things","importance":"IoT is connecting billions of devices to the internet — from smart homes to industrial automation. As a CSE student, IoT combines your software skills with hardware interaction. IoT engineers are in massive demand for smart city, healthcare, agriculture, and industrial automation projects.","whyMatters":["IoT market is worth $500+ billion and growing rapidly","Smart cities, healthcare monitoring, industrial automation all use IoT","IoT combines CSE software skills with hardware and networking","Edge computing and embedded systems are the future of computing"],"units":[{"title":"Unit I — IoT Fundamentals & M2M","short":"IoT Vision, M2M, Design Principles","topics":["IoT vision, definition, conceptual framework, architectural view","Technology behind IoT, Sources of IoT","M2M Communication, IoT examples (smart home, health monitoring)","IoT/M2M systems layers and design standardization","Communication technologies, data enrichment and consolidation"],"query":"IoT+Internet+of+Things+M2M+Architecture+BTech+AKTU"},{"title":"Unit II — IoT Hardware & Embedded Platforms","short":"Sensors, Arduino, Raspberry Pi","topics":["Sensors: digital sensors, actuators, types and applications","RFID technology and wireless sensor networks","Participatory sensing technology","Embedded computing basics for IoT","Hardware platforms: Arduino, Raspberry Pi, Beagle Bone, Intel Galileo, ARM Cortex"],"query":"IoT+Hardware+Arduino+Raspberry+Pi+Sensors+Embedded+BTech+AKTU"},{"title":"Unit III — IoT Networking & Protocols","short":"MAC, Routing, Data Aggregation","topics":["Wireless Medium Access Control issues for IoT","MAC protocol survey for IoT networks","Survey of routing protocols for sensor networks","Sensor deployment and Node discovery","Data aggregation and dissemination in IoT"],"query":"IoT+Networking+MAC+Protocols+Routing+Sensor+Networks+BTech+AKTU"},{"title":"Unit IV — Arduino Programming for IoT","short":"Arduino IDE, Libraries, Emulator","topics":["Arduino Platform: board anatomy, pin configuration","Arduino IDE: coding environment, compilation","Using emulator for testing without hardware","Using Arduino libraries for sensors and modules","Programming Arduino for IoT: reading sensors, controlling actuators"],"query":"Arduino+Programming+IoT+BTech+AKTU+sensors+actuators"},{"title":"Unit V — IoT Challenges & Applications","short":"Smart City, E-health, Automation","topics":["IoT Design Challenges: development, security, scalability challenges","IoT Security Challenges and solutions","Smart Metering: energy monitoring applications","E-health: patient monitoring, wearable devices","City Automation: smart street lights, traffic management","Home automation, smart cards, automotive applications"],"query":"IoT+Applications+Smart+City+Home+Automation+Healthcare+BTech+AKTU"}],"tips":[{"h":"Arduino Hands-On","d":"<strong>Run every Arduino program on simulator (Tinkercad)</strong> if no hardware available — practicals test actual coding."},{"h":"Architecture Diagrams","d":"<strong>Draw IoT architecture diagrams with all layers clearly labeled</strong> — 5-mark theory questions regularly."},{"h":"Protocol Comparison","d":"<strong>Make a table comparing IoT communication protocols</strong> (MQTT, CoAP, HTTP, Zigbee) — asked in theory."},{"h":"Real Applications","d":"<strong>Know 3-4 real IoT application examples with architecture</strong> — examiners reward application-focused answers."}]},"BCS071":{"name":"Cloud Computing","importance":"Cloud Computing has fundamentally changed how software is deployed and scaled. AWS, Azure, and Google Cloud power 90%+ of the internet. Understanding cloud architecture, virtualization, and services is now a mandatory skill for backend developers, DevOps engineers, and system architects.","whyMatters":["90%+ of internet runs on cloud platforms (AWS, Azure, GCP)","Cloud computing skills are in top 5 most demanded tech skills","Scalability concepts from cloud are in every system design interview","DevOps, containerization, and microservices all build on cloud foundations"],"units":[{"title":"Unit I — Introduction to Cloud Computing","short":"Cloud Definition, Elasticity","topics":["Definition of Cloud, evolution of cloud computing","Underlying principles of parallel and distributed computing","Cloud characteristics: on-demand, elasticity, pay-per-use","Elasticity in cloud: automatic scaling up and down","On-demand provisioning of resources"],"query":"Cloud+Computing+Introduction+Elasticity+Distributed+Computing+BTech+AKTU"},{"title":"Unit II — Virtualization & SOA","short":"Virtualization, REST, Web Services","topics":["Service Oriented Architecture (SOA), REST and Systems of Systems","Web Services, Publish-Subscribe Model","Virtualization: types — full, para, OS-level, hardware-level","Implementation levels: CPU, memory, I/O device virtualization","Virtualization tools and mechanisms","Disaster Recovery using virtualization"],"query":"Virtualization+SOA+REST+Web+Services+Cloud+Computing+BTech+AKTU"},{"title":"Unit III — Cloud Architecture & Storage","short":"IaaS, PaaS, SaaS, S3","topics":["Layered cloud architecture design","NIST Cloud Computing Reference Architecture","Public, Private, Hybrid, Community clouds — comparison","Service models: IaaS, PaaS, SaaS — examples and differences","Cloud Storage: Storage-as-a-Service, advantages","Cloud storage providers: Amazon S3, Google Cloud Storage"],"query":"IaaS+PaaS+SaaS+Cloud+Architecture+Storage+S3+BTech+AKTU"},{"title":"Unit IV — Resource Management & Security","short":"Provisioning, Security, IAM","topics":["Inter-Cloud Resource Management","Resource provisioning methods: static, dynamic","Global exchange of cloud resources","Cloud Security overview: challenges and attack vectors","Software-as-a-Service security considerations","Security Governance, Virtual Machine Security, IAM"],"query":"Cloud+Security+Resource+Management+IAM+Provisioning+BTech+AKTU"},{"title":"Unit V — Cloud Technologies & Federation","short":"Hadoop, OpenStack, Federation","topics":["Hadoop on Cloud: MapReduce framework","Virtual Box, Google App Engine programming environment","OpenStack: architecture and components","Federation in Cloud: four levels of federation","Federated services and applications","Future of Cloud Federation and hybrid multi-cloud"],"query":"Hadoop+MapReduce+OpenStack+Google+App+Engine+Cloud+Federation+BTech+AKTU"}],"tips":[{"h":"IaaS vs PaaS vs SaaS","d":"<strong>Make a clear comparison table with examples</strong> — this distinction is asked in every AKTU cloud exam."},{"h":"Virtualization Types","d":"<strong>Understand all virtualization types with real-world hypervisors</strong> (VMware, VirtualBox, KVM) — important theory."},{"h":"Cloud Provider Examples","d":"<strong>Map each service model to real cloud providers</strong> — AWS EC2 (IaaS), AWS Lambda (PaaS), Gmail (SaaS)."},{"h":"Deployment Models","d":"<strong>Know when to choose public vs private vs hybrid cloud</strong> — scenario-based questions appear every year."}]},"BCS072":{"name":"Cryptography & Network Security","importance":"Cybersecurity is one of the fastest-growing fields in technology with massive talent shortages. Cryptography underlies every secure transaction, every HTTPS connection, and every encrypted message. Understanding security is mandatory for any serious software developer working on production systems.","whyMatters":["Every HTTPS website uses RSA and AES from this subject","Digital signatures enable secure authentication in all banking apps","Cybersecurity engineers are among highest-paid professionals","Data breaches and security vulnerabilities cost companies billions"],"units":[{"title":"Unit I — Classical & Symmetric Encryption","short":"DES, AES, Block Ciphers","topics":["Security attacks, services and mechanisms overview","Classical techniques: substitution and transposition ciphers, steganography","Stream and block ciphers","DES: structure, Feistel network, strength, Triple DES","AES: encryption and decryption process","Block cipher modes: ECB, CBC, CFB, OFB, CTR"],"query":"DES+AES+Block+Cipher+Cryptography+Network+Security+BTech+AKTU"},{"title":"Unit II — Public Key Cryptography","short":"RSA, Diffie-Hellman, Number Theory","topics":["Groups, fields, GF(p), modular arithmetic","Prime numbers, Extended Euclidean Algorithm","Fermat and Euler theorems, Chinese Remainder Theorem","Discrete Logarithm Problem","RSA algorithm: key generation, encryption, decryption, security","Advanced Encryption Standard (AES) mathematical foundations"],"query":"RSA+Public+Key+Cryptography+Diffie+Hellman+Modular+Arithmetic+BTech+AKTU"},{"title":"Unit III — Hash Functions & Digital Signatures","short":"SHA, Digital Signature, MAC","topics":["Message Authentication Codes (MAC)","Hash functions: properties, birthday attacks","Secure Hash Algorithm (SHA): SHA-1, SHA-256","Digital Signatures: purpose and properties","ElGamal Digital Signature, DSS (Digital Signature Standard)","Proof of digital signature algorithm"],"query":"Hash+Functions+SHA+Digital+Signature+MAC+Cryptography+BTech+AKTU"},{"title":"Unit IV — Key Management & Authentication","short":"PKI, Kerberos, PGP, S/MIME","topics":["Symmetric key distribution methods","Diffie-Hellman Key Exchange protocol","Public Key Distribution, X.509 Certificates","Public Key Infrastructure (PKI)","Authentication Applications: Kerberos protocol","Email security: PGP (Pretty Good Privacy), S/MIME"],"query":"Key+Management+PKI+Kerberos+PGP+Authentication+Cryptography+BTech+AKTU"},{"title":"Unit V — Network Security Protocols","short":"IPSec, SSL, Firewall, IDS","topics":["IP Security (IPSec): architecture, authentication header (AH), ESP","Combining security associations, key management in IPSec","Secure Socket Layer (SSL) / TLS protocol","Secure Electronic Transaction (SET)","System Security: intrusion types, intrusion detection systems (IDS)","Viruses, malware, firewalls — types and configurations"],"query":"IPSec+SSL+TLS+Firewall+Intrusion+Detection+Network+Security+BTech+AKTU"}],"tips":[{"h":"RSA Numericals","d":"<strong>Practice RSA key generation and encryption/decryption numericals</strong> — appears in every AKTU Cryptography exam."},{"h":"DES Steps","d":"<strong>Memorize DES: 16 rounds, 64-bit block, 56-bit key, Feistel structure</strong> — theory questions every year."},{"h":"Hash vs MAC vs Digital Sign","d":"<strong>Know the difference between hash, MAC, and digital signatures</strong> — comparison question is standard."},{"h":"Stallings Book","d":"Follow <strong>William Stallings Cryptography and Network Security</strong> — perfectly aligned with AKTU syllabus."}]},"BCS073":{"name":"Design & Development of Applications","importance":"Mobile app development is one of the most in-demand and lucrative skills in technology. With 6+ billion smartphone users globally, mobile apps represent a massive market. This subject teaches Android and iOS development — directly enabling you to build and publish real applications.","whyMatters":["6+ billion smartphone users represent a massive market for apps","Android and iOS development are among highest-paying dev skills","Mobile apps are the primary interface for most digital services today","Full-stack mobile developers (frontend + backend + mobile) are rare and well-paid"],"units":[{"title":"Unit I — Mobile App Introduction","short":"Mobile Market, Requirements","topics":["Mobile applications market and business drivers","Publishing and delivery of mobile applications","Requirements gathering and validation for mobile apps","Embedded systems basics and overview","Technology and business trends in mobile"],"query":"Mobile+Applications+Introduction+Android+iOS+BTech+AKTU"},{"title":"Unit II — Basic Mobile App Design","short":"Design Constraints, UI, UX","topics":["Basics of embedded system design for mobile","Embedded OS for mobile platforms","Design constraints: hardware and software related","Architecting mobile applications: patterns and layers","User interface design: touch events, gestures, usability","Quality constraints: performance, security, availability"],"query":"Mobile+App+Design+UI+UX+Gestures+Touch+Events+BTech+AKTU"},{"title":"Unit III — Advanced Mobile Design","short":"Multimedia, GPS, Cloud Integration","topics":["Designing with multimedia and web access capabilities","Integration with GPS: location-based services","Social media networking application integration","Accessing applications hosted in cloud environment","Design patterns for mobile applications: MVC, MVVM"],"query":"Advanced+Mobile+Design+GPS+Cloud+Social+Media+BTech+AKTU"},{"title":"Unit IV — Android Development","short":"Android Architecture, SQLite, Maps","topics":["Introduction to Android, development environment setup","Android architecture: kernel, libraries, runtime, applications","Activities and Views, Android lifecycle","Interacting with UI, event handling","Persisting data using SQLite database","Google Maps, GPS, WiFi integration, social media"],"query":"Android+Development+Architecture+SQLite+Activities+BTech+AKTU"},{"title":"Unit V — iOS Development & Swift","short":"iOS, Objective-C, Swift, Core Data","topics":["Introduction to Objective-C basics","iOS features and UI implementation","Touch frameworks and gesture recognition","Data persistence using Core Data and SQLite on iOS","Location-aware applications using Core Location and Map Kit","Swift: introduction, features, syntax, iOS development with Swift"],"query":"iOS+Development+Swift+Objective+C+Core+Data+BTech+AKTU"}],"tips":[{"h":"Android Studio Setup","d":"<strong>Install Android Studio and run every tutorial code example</strong> — practicals test actual running app creation."},{"h":"Activity Lifecycle","d":"<strong>Draw the Android Activity Lifecycle diagram from memory</strong> — always asked in AKTU theory exams."},{"h":"SQLite Integration","d":"<strong>Practice building a CRUD app with SQLite in Android</strong> — most common practical exam requirement."},{"h":"Design Pattern Comparison","d":"<strong>Know MVC vs MVVM for mobile apps</strong> — architectural pattern questions appear in theory."}]},"DEFAULT":{"name":"This Subject","importance":"This is a core subject in your B.Tech CSE curriculum. Mastering it strengthens your academic profile, builds problem-solving skills, and prepares you for technical interviews and professional software development roles.","whyMatters":["Core curriculum subject directly affecting your overall CGPA","Builds analytical and problem-solving skills used in all roles","Relevant to real-world software engineering and industry needs","May appear in campus placement written tests and interviews"],"units":[{"title":"Unit I — Fundamentals","short":"Core Concepts & Definitions","topics":["Basic definitions and fundamental concepts of the subject","Introduction to key principles and theory","Historical background and motivation for study"],"query":"BTech+CSE+AKTU+subject+unit+1+fundamentals+important+topics"},{"title":"Unit II — Core Theory","short":"Main Theoretical Framework","topics":["Main theoretical framework and key algorithms","Core principles and mathematical foundations","Important theorems and their proofs"],"query":"BTech+CSE+AKTU+subject+theory+concepts+unit+2+important"},{"title":"Unit III — Practical Applications","short":"Real-World Use Cases","topics":["Real-world applications and case studies","Problem-solving methodology and approach","Industry relevance and use cases"],"query":"BTech+CSE+AKTU+subject+applications+unit+3+practical"},{"title":"Unit IV — Advanced Topics","short":"Advanced Concepts","topics":["Advanced theoretical concepts building on core","Complex problem types and solution strategies","Extensions and modern developments"],"query":"BTech+CSE+AKTU+advanced+topics+unit+4+important"},{"title":"Unit V — Exam Preparation","short":"PYQs & Important Questions","topics":["Previous year AKTU question patterns and important questions","Numerical problems and solution techniques","Short answer and long answer writing strategies"],"query":"BTech+CSE+AKTU+previous+year+question+paper+exam+preparation+important"}],"tips":[{"h":"AKTU PYQs First","d":"<strong>Solve last 5 years AKTU question papers</strong> — 70% questions repeat every year with slight variations."},{"h":"Unit-wise Notes","d":"<strong>Make concise unit-wise notes in your own words</strong> — revision is 3x faster with personalized notes."},{"h":"Textbook Examples","d":"<strong>Solve every example in the AKTU prescribed textbook</strong> — questions are always textbook-aligned."},{"h":"Study Group","d":"<strong>Form a study group of 3-4 classmates</strong> — teaching others is the fastest way to solidify understanding."}]}}'::jsonb)
on conflict (key) do update set value = excluded.value, updated_at = now();

